(535,329,$mw$05C25A27A6484D95B1FDAA9C3181C9AD0768DA0C34270FA9560F16B1AC4EA2BB$mw$,$mw$a043fe6debac2ac9156c3ffe40127f7c$mw$,$mw$$mw$,$mw${"Id":329,"StageId":4,"CategoryId":13,"Points":15,"TitleAr":"إذا \\(f(x,y)=2x^2y+1y^2\\)، أوجد \\(\\partial f/\\partial y\\) عند (2،3).","TitleEn":"Given \\(f(x,y)=2x^2y+1y^2\\), evaluate \\(\\partial f/\\partial y\\) at (2,3).","QuestionTextAr":"إذا \\(f(x,y)=2x^2y+1y^2\\)، أوجد \\(\\partial f/\\partial y\\) عند (2،3).","QuestionTextEn":"Given \\(f(x,y)=2x^2y+1y^2\\), evaluate \\(\\partial f/\\partial y\\) at (2,3).","DetailedSolutionAr":"قانون المشتقة الجزئية بالنسبة إلى ص: نعامل س كثابت. للدالة f(س،ص) = 2س²ص + 1ص² نجد ∂f/∂ص = 2س² + 2ص. عند (2،3) نحسب 2 × 2² + 2 × 3 = 8 + 6 = 14.","DetailedSolutionEn":"Partial derivative with respect to y: Treat x as constant. For f(x,y)=2x²y+1y², ∂f/∂y=2x²+2y. At (2,3), calculate 2×2²+2×3=8+6=14.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":1305,"Order":1,"LatexCode":"17","IsCorrect":false},{"Id":1306,"Order":2,"LatexCode":"12","IsCorrect":false},{"Id":1307,"Order":3,"LatexCode":"14","IsCorrect":true},{"Id":1308,"Order":4,"LatexCode":"15","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"حدد المتغير المطلوب في المشتقة الجزئية.","En":"Identify the requested partial differentiation variable."},{"Ar":"اشتق التعبير مع تثبيت المتغير الآخر، ثم عوّض النقطة.","En":"Differentiate holding the other variable fixed, then evaluate at the point."}],"Title":{"Ar":"إذا \\(f(x,y)=2x^2y+1y^2\\)، أوجد \\(\\partial f/\\partial y\\) عند (2،3).","En":"Given \\(f(x,y)=2x^2y+1y^2\\), evaluate \\(\\partial f/\\partial y\\) at (2,3)."},"Points":15,"Options":[{"Reason":{"Ar":"يعطي الحد الأول $8$ والثاني $6$. القيمة $17$ تتطلب أن يكون مجموع الحدين مختلفاً بمقدار $3$، وهو خطأ في الاشتقاق أو التعويض.","En":"The first term gives $8$ and the second $6$. The choice $17$ differs from their sum by $3$, indicating a differentiation or substitution error."},"ErrorType":"misconception","IsCorrect":false,"LatexCode":"17"},{"Reason":{"Ar":"يعطي الحد الأول $8$ والثاني $6$. القيمة $12$ تتطلب أن يكون مجموع الحدين مختلفاً بمقدار $-2$، وهو خطأ في الاشتقاق أو التعويض.","En":"The first term gives $8$ and the second $6$. The choice $12$ differs from their sum by $-2$, indicating a differentiation or substitution error."},"ErrorType":"misconception","IsCorrect":false,"LatexCode":"12"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"14"},{"Reason":{"Ar":"يعطي الحد الأول $8$ والثاني $6$. القيمة $15$ تتطلب أن يكون مجموع الحدين مختلفاً بمقدار $1$، وهو خطأ في الاشتقاق أو التعويض.","En":"The first term gives $8$ and the second $6$. The choice $15$ differs from their sum by $1$, indicating a differentiation or substitution error."},"ErrorType":"misconception","IsCorrect":false,"LatexCode":"15"}],"StageId":4,"Question":{"Ar":"إذا \\(f(x,y)=2x^2y+1y^2\\)، أوجد \\(\\partial f/\\partial y\\) عند (2،3).","En":"Given \\(f(x,y)=2x^2y+1y^2\\), evaluate \\(\\partial f/\\partial y\\) at (2,3)."},"Solution":{"Idea":{"Ar":"نثبت x عند الاشتقاق بالنسبة إلى y ثم نعوض إحداثيي النقطة.","En":"Hold x fixed when differentiating in y, then substitute the point."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"عند الاشتقاق بالنسبة إلى $y$، يبقى $x$ ثابتاً، ومشتقة $2x^2y$ هي $2x^2$.","En":"Holding $x$ fixed, differentiate $2x^2y$ in $y$ to get $2x^2$."},{"Ar":"مشتقة $1y^2$ هي $2y$. نجمع الحدين قبل التعويض.","En":"The derivative of $1y^2$ is $2y$. Add the terms before substitution."}],"Result":{"Ar":"$14$","En":"$14$"},"CommonError":{"Ar":"لا تعوض في الدالة الأصلية قبل الاشتقاق.","En":"Do not substitute into the original function before differentiation."},"FormulaLatex":"\\frac{\\partial f}{\\partial y}=2x^2+2y","Substitution":{"Ar":"$2(2)^2+2(3)=8+6=14$","En":"$2(2)^2+2(3)=8+6=14$"},"Verification":{"Ar":"$\\lim_{h\\to0}\\frac{f(2,3+h)-f(2,3)}{h}=\\lim_{h\\to0}(14+1h)=14$","En":"$\\lim_{h\\to0}\\frac{f(2,3+h)-f(2,3)}{h}=\\lim_{h\\to0}(14+1h)=14$"}},"TrackIds":[13,21],"CategoryId":13,"PrimarySkillId":57,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"حدد المتغير المطلوب في المشتقة الجزئية.","En":"Identify the requested partial differentiation variable."},{"Ar":"اشتق التعبير مع تثبيت المتغير الآخر، ثم عوّض النقطة.","En":"Differentiate holding the other variable fixed, then evaluate at the point."}],"Solution":{"Idea":{"Ar":"نثبت x عند الاشتقاق بالنسبة إلى y ثم نعوض إحداثيي النقطة.","En":"Hold x fixed when differentiating in y, then substitute the point."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"عند الاشتقاق بالنسبة إلى $y$، يبقى $x$ ثابتاً، ومشتقة $2x^2y$ هي $2x^2$.","En":"Holding $x$ fixed, differentiate $2x^2y$ in $y$ to get $2x^2$."},{"Ar":"مشتقة $1y^2$ هي $2y$. نجمع الحدين قبل التعويض.","En":"The derivative of $1y^2$ is $2y$. Add the terms before substitution."}],"Result":{"Ar":"$14$","En":"$14$"},"CommonError":{"Ar":"لا تعوض في الدالة الأصلية قبل الاشتقاق.","En":"Do not substitute into the original function before differentiation."},"FormulaLatex":"\\frac{\\partial f}{\\partial y}=2x^2+2y","Substitution":{"Ar":"$2(2)^2+2(3)=8+6=14$","En":"$2(2)^2+2(3)=8+6=14$"},"Verification":{"Ar":"$\\lim_{h\\to0}\\frac{f(2,3+h)-f(2,3)}{h}=\\lim_{h\\to0}(14+1h)=14$","En":"$\\lim_{h\\to0}\\frac{f(2,3+h)-f(2,3)}{h}=\\lim_{h\\to0}(14+1h)=14$"}},"Distractors":[{"ErrorType":"misconception","Reason":{"Ar":"يعطي الحد الأول $8$ والثاني $6$. القيمة $17$ تتطلب أن يكون مجموع الحدين مختلفاً بمقدار $3$، وهو خطأ في الاشتقاق أو التعويض.","En":"The first term gives $8$ and the second $6$. The choice $17$ differs from their sum by $3$, indicating a differentiation or substitution error."},"Order":1},{"ErrorType":"misconception","Reason":{"Ar":"يعطي الحد الأول $8$ والثاني $6$. القيمة $12$ تتطلب أن يكون مجموع الحدين مختلفاً بمقدار $-2$، وهو خطأ في الاشتقاق أو التعويض.","En":"The first term gives $8$ and the second $6$. The choice $12$ differs from their sum by $-2$, indicating a differentiation or substitution error."},"Order":2},{"ErrorType":"","Reason":null,"Order":3},{"ErrorType":"misconception","Reason":{"Ar":"يعطي الحد الأول $8$ والثاني $6$. القيمة $15$ تتطلب أن يكون مجموع الحدين مختلفاً بمقدار $1$، وهو خطأ في الاشتقاق أو التعويض.","En":"The first term gives $8$ and the second $6$. The choice $15$ differs from their sum by $1$, indicating a differentiation or substitution error."},"Order":4}]}$mw$,$mw$نثبت x عند الاشتقاق بالنسبة إلى y ثم نعوض إحداثيي النقطة.

$\frac{\partial f}{\partial y}=2x^2+2y$

1. عند الاشتقاق بالنسبة إلى $y$، يبقى $x$ ثابتاً، ومشتقة $2x^2y$ هي $2x^2$.

2. مشتقة $1y^2$ هي $2y$. نجمع الحدين قبل التعويض.

$2(2)^2+2(3)=8+6=14$

$14$ بلا وحدة قياس

$\lim_{h\to0}\frac{f(2,3+h)-f(2,3)}{h}=\lim_{h\to0}(14+1h)=14$

لا تعوض في الدالة الأصلية قبل الاشتقاق.$mw$,$mw$Hold x fixed when differentiating in y, then substitute the point.

$\frac{\partial f}{\partial y}=2x^2+2y$

1. Holding $x$ fixed, differentiate $2x^2y$ in $y$ to get $2x^2$.

2. The derivative of $1y^2$ is $2y$. Add the terms before substitution.

$2(2)^2+2(3)=8+6=14$

$14$ Dimensionless

$\lim_{h\to0}\frac{f(2,3+h)-f(2,3)}{h}=\lim_{h\to0}(14+1h)=14$

Do not substitute into the original function before differentiation.$mw$),
(536,330,$mw$2E0F2907961A02A418376034B274D76FEFC4C45A5D424E6B14FF80219F2A075D$mw$,$mw$774431249761ca7fc39f0e5cbabf6690$mw$,$mw$$mw$,$mw${"Id":330,"StageId":4,"CategoryId":13,"Points":15,"TitleAr":"ما تدرج \\(f(x,y)=x^2+y^2\\) عند النقطة (2،3)؟","TitleEn":"Find gradient of \\(f(x,y)=x^2+y^2\\) at (2,3).","QuestionTextAr":"ما تدرج \\(f(x,y)=x^2+y^2\\) عند النقطة (2،3)؟","QuestionTextEn":"Find gradient of \\(f(x,y)=x^2+y^2\\) at (2,3).","DetailedSolutionAr":"قانون التدرج: ∇f(س،ص) = (∂f/∂س،∂f/∂ص). للدالة f(س،ص) = س² + ص²، التدرج هو (2س،2ص). عند النقطة (2،3) تصبح المركبتان (2 × 2،2 × 3) = (4،6). هذا متجه وليس عدداً واحداً.","DetailedSolutionEn":"Gradient rule: ∇f=(∂f/∂x,∂f/∂y). For f(x,y)=x²+y², ∇f=(2x,2y). At (2,3), the result is (2×2,2×3)=(4,6). A gradient is a vector, not a scalar.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":1309,"Order":1,"LatexCode":"(4,-6)","IsCorrect":false},{"Id":1310,"Order":2,"LatexCode":"(4,6)","IsCorrect":true},{"Id":1311,"Order":3,"LatexCode":"(2,3)","IsCorrect":false},{"Id":1312,"Order":4,"LatexCode":"(6,4)","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"احسب المشتقتين الجزئيتين.","En":"Compute both partial derivatives."},{"Ar":"رتب مشتقة x أولاً ومشتقة y ثانياً، ثم عوض النقطة.","En":"Order the x-partial first and y-partial second, then evaluate."}],"Title":{"Ar":"ما تدرج \\(f(x,y)=x^2+y^2\\) عند النقطة (2،3)؟","En":"Find gradient of \\(f(x,y)=x^2+y^2\\) at (2,3)."},"Points":15,"Options":[{"Reason":{"Ar":"غيّر إشارة المركبة الثانية مع أن الإحداثي الثاني موجب ومشتقته تساوي ضعفه.","En":"Negates the second component even though the positive y-coordinate yields a positive derivative."},"ErrorType":"misconception","IsCorrect":false,"LatexCode":"(4,-6)"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"(4,6)"},{"Reason":{"Ar":"أعاد إحداثيي النقطة دون اشتقاق.","En":"Returns the input coordinates without differentiation."},"ErrorType":"misconception","IsCorrect":false,"LatexCode":"(2,3)"},{"Reason":{"Ar":"بدّل ترتيب المشتقتين الجزئيتين.","En":"Swaps the two partial derivatives."},"ErrorType":"misconception","IsCorrect":false,"LatexCode":"(6,4)"}],"StageId":4,"Question":{"Ar":"ما تدرج \\(f(x,y)=x^2+y^2\\) عند النقطة (2،3)؟","En":"Find gradient of \\(f(x,y)=x^2+y^2\\) at (2,3)."},"Solution":{"Idea":{"Ar":"التدرج متجه يجمع المشتقتين الجزئيتين بالترتيب.","En":"The gradient is the ordered vector of partial derivatives."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"نشتق $x^2+y^2$ بالنسبة إلى $x$ مع تثبيت $y$، فنحصل على $2x$.","En":"Differentiate $x^2+y^2$ in $x$ with $y$ fixed, giving $2x$."},{"Ar":"نشتق بالنسبة إلى $y$ مع تثبيت $x$ فنحصل على $2y$؛ نرتب المركبتين بهذا الترتيب.","En":"Differentiate in $y$ with $x$ fixed to get $2y$; retain this component order."}],"Result":{"Ar":"$(4,6)$","En":"$(4,6)$"},"CommonError":{"Ar":"لا تبدل ترتيب مركبتي التدرج.","En":"Do not swap gradient components."},"FormulaLatex":"\\nabla f=(2x,2y)","Substitution":{"Ar":"$\\nabla f(2,3)=(2\\cdot2,2\\cdot3)=(4,6)$","En":"$\\nabla f(2,3)=(2\\cdot2,2\\cdot3)=(4,6)$"},"Verification":{"Ar":"$f_x(2,3)=4,\\quad f_y(2,3)=6$","En":"$f_x(2,3)=4,\\quad f_y(2,3)=6$"}},"TrackIds":[13,21],"CategoryId":13,"PrimarySkillId":59,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"احسب المشتقتين الجزئيتين.","En":"Compute both partial derivatives."},{"Ar":"رتب مشتقة x أولاً ومشتقة y ثانياً، ثم عوض النقطة.","En":"Order the x-partial first and y-partial second, then evaluate."}],"Solution":{"Idea":{"Ar":"التدرج متجه يجمع المشتقتين الجزئيتين بالترتيب.","En":"The gradient is the ordered vector of partial derivatives."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"نشتق $x^2+y^2$ بالنسبة إلى $x$ مع تثبيت $y$، فنحصل على $2x$.","En":"Differentiate $x^2+y^2$ in $x$ with $y$ fixed, giving $2x$."},{"Ar":"نشتق بالنسبة إلى $y$ مع تثبيت $x$ فنحصل على $2y$؛ نرتب المركبتين بهذا الترتيب.","En":"Differentiate in $y$ with $x$ fixed to get $2y$; retain this component order."}],"Result":{"Ar":"$(4,6)$","En":"$(4,6)$"},"CommonError":{"Ar":"لا تبدل ترتيب مركبتي التدرج.","En":"Do not swap gradient components."},"FormulaLatex":"\\nabla f=(2x,2y)","Substitution":{"Ar":"$\\nabla f(2,3)=(2\\cdot2,2\\cdot3)=(4,6)$","En":"$\\nabla f(2,3)=(2\\cdot2,2\\cdot3)=(4,6)$"},"Verification":{"Ar":"$f_x(2,3)=4,\\quad f_y(2,3)=6$","En":"$f_x(2,3)=4,\\quad f_y(2,3)=6$"}},"Distractors":[{"ErrorType":"misconception","Reason":{"Ar":"غيّر إشارة المركبة الثانية مع أن الإحداثي الثاني موجب ومشتقته تساوي ضعفه.","En":"Negates the second component even though the positive y-coordinate yields a positive derivative."},"Order":1},{"ErrorType":"","Reason":null,"Order":2},{"ErrorType":"misconception","Reason":{"Ar":"أعاد إحداثيي النقطة دون اشتقاق.","En":"Returns the input coordinates without differentiation."},"Order":3},{"ErrorType":"misconception","Reason":{"Ar":"بدّل ترتيب المشتقتين الجزئيتين.","En":"Swaps the two partial derivatives."},"Order":4}]}$mw$,$mw$التدرج متجه يجمع المشتقتين الجزئيتين بالترتيب.

$\nabla f=(2x,2y)$

1. نشتق $x^2+y^2$ بالنسبة إلى $x$ مع تثبيت $y$، فنحصل على $2x$.

2. نشتق بالنسبة إلى $y$ مع تثبيت $x$ فنحصل على $2y$؛ نرتب المركبتين بهذا الترتيب.

$\nabla f(2,3)=(2\cdot2,2\cdot3)=(4,6)$

$(4,6)$ بلا وحدة قياس

$f_x(2,3)=4,\quad f_y(2,3)=6$

لا تبدل ترتيب مركبتي التدرج.$mw$,$mw$The gradient is the ordered vector of partial derivatives.

$\nabla f=(2x,2y)$

1. Differentiate $x^2+y^2$ in $x$ with $y$ fixed, giving $2x$.

2. Differentiate in $y$ with $x$ fixed to get $2y$; retain this component order.

$\nabla f(2,3)=(2\cdot2,2\cdot3)=(4,6)$

$(4,6)$ Dimensionless

$f_x(2,3)=4,\quad f_y(2,3)=6$

Do not swap gradient components.$mw$),
(537,331,$mw$FB5FBBDEC47DA297239A12C80CE692DB4AA12C12C2AD0F161BE9175332E3A8A3$mw$,$mw$fc3646986cdaaa27d32e7a5f5a399ccf$mw$,$mw$$mw$,$mw${"Id":331,"StageId":4,"CategoryId":13,"Points":15,"TitleAr":"لدالة \\(f(x,y)=x^2+3y^2\\)، احسب المشتقة الاتجاهية عند (1،2) باتجاه محور x الموجب.","TitleEn":"For \\(f(x,y)=x^2+3y^2\\), find directional derivative at (1,2) in positive x-direction.","QuestionTextAr":"لدالة \\(f(x,y)=x^2+3y^2\\)، احسب المشتقة الاتجاهية عند (1،2) باتجاه محور x الموجب.","QuestionTextEn":"For \\(f(x,y)=x^2+3y^2\\), find directional derivative at (1,2) in positive x-direction.","DetailedSolutionAr":"قانون المشتقة الاتجاهية في اتجاه وحدة u: Dᵤf = ∇f · u. للدالة f(س،ص) = س² + 3ص² يكون ∇f = (2س،6ص). اتجاه س الموجب يساوي متجه الوحدة u=(1،0)، لذا Dᵤf = 2س × 1 + 6ص × 0 = 2س. عند (1،2) الناتج 2.","DetailedSolutionEn":"Directional derivative: D_u f = ∇f · u for a unit direction u. For f(x,y)=x²+3y², ∇f=(2x,6y). The positive x-direction is u=(1,0), so D_u f=2x×1+6y×0=2x. At (1,2), this equals 2.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":1313,"Order":1,"LatexCode":"2","IsCorrect":true},{"Id":1314,"Order":2,"LatexCode":"3","IsCorrect":false},{"Id":1315,"Order":3,"LatexCode":"5","IsCorrect":false},{"Id":1316,"Order":4,"LatexCode":"0","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"حدد متجه وحدة الاتجاه الموجب لمحور x.","En":"Identify the positive x-axis unit direction."},{"Ar":"احسب التدرج عند النقطة ثم اضربه قياسياً في متجه الاتجاه.","En":"Evaluate the gradient at the point and dot it with the direction."}],"Title":{"Ar":"لدالة \\(f(x,y)=x^2+3y^2\\)، احسب المشتقة الاتجاهية عند (1،2) باتجاه محور x الموجب.","En":"For \\(f(x,y)=x^2+3y^2\\), find directional derivative at (1,2) in positive x-direction."},"Points":15,"Options":[{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"2"},{"Reason":{"Ar":"في الاتجاه $(1,0)$ تكون مساهمة المركبة الرأسية صفراً. القيمة $3$ لا تساوي المركبة الأفقية $2\\cdot1$؛ راجع حساب الإسقاط.","En":"In direction $(1,0)$ the vertical contribution is zero. The choice $3$ is not the horizontal component $2\\cdot1$; recheck the projection."},"ErrorType":"misconception","IsCorrect":false,"LatexCode":"3"},{"Reason":{"Ar":"في الاتجاه $(1,0)$ تكون مساهمة المركبة الرأسية صفراً. القيمة $5$ لا تساوي المركبة الأفقية $2\\cdot1$؛ راجع حساب الإسقاط.","En":"In direction $(1,0)$ the vertical contribution is zero. The choice $5$ is not the horizontal component $2\\cdot1$; recheck the projection."},"ErrorType":"misconception","IsCorrect":false,"LatexCode":"5"},{"Reason":{"Ar":"ألغى المركبتين رغم أن مركبة الاتجاه الأفقية تساوي واحداً.","En":"Cancels both components although the horizontal direction component is one."},"ErrorType":"misconception","IsCorrect":false,"LatexCode":"0"}],"StageId":4,"Question":{"Ar":"لدالة \\(f(x,y)=x^2+3y^2\\)، احسب المشتقة الاتجاهية عند (1،2) باتجاه محور x الموجب.","En":"For \\(f(x,y)=x^2+3y^2\\), find directional derivative at (1,2) in positive x-direction."},"Solution":{"Idea":{"Ar":"المشتقة الاتجاهية هي الضرب القياسي للتدرج بمتجه وحدة الاتجاه.","En":"The directional derivative is the gradient dotted with the unit direction vector."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"المشتقتان الجزئيتان هما $2x$ و$6y$؛ الاتجاه الموجب لمحور $x$ متجه وحدته $(1,0)$.","En":"The partial derivatives are $2x$ and $6y$; the positive x-direction has unit vector $(1,0)$."},{"Ar":"التدرج عند النقطة يساوي $(2,12)$، والجداء النقطي ينتقي المركبة الأولى.","En":"The gradient at the point is $(2,12)$; the dot product selects its first component."}],"Result":{"Ar":"$2$","En":"$2$"},"CommonError":{"Ar":"لا تستخدم معيار التدرج بدلاً من إسقاطه الاتجاهي.","En":"Do not use the gradient norm instead of its directional projection."},"FormulaLatex":"D_{\\mathbf u}f=\\nabla f\\cdot\\mathbf u,\\quad \\mathbf u=(1,0)","Substitution":{"Ar":"$(2,12)\\cdot(1,0)=2+0=2$","En":"$(2,12)\\cdot(1,0)=2+0=2$"},"Verification":{"Ar":"$\\lim_{h\\to0}\\frac{f(1+h,2)-f(1,2)}{h}=\\lim_{h\\to0}(2+h)=2$","En":"$\\lim_{h\\to0}\\frac{f(1+h,2)-f(1,2)}{h}=\\lim_{h\\to0}(2+h)=2$"}},"TrackIds":[13,21],"CategoryId":13,"PrimarySkillId":60,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"حدد متجه وحدة الاتجاه الموجب لمحور x.","En":"Identify the positive x-axis unit direction."},{"Ar":"احسب التدرج عند النقطة ثم اضربه قياسياً في متجه الاتجاه.","En":"Evaluate the gradient at the point and dot it with the direction."}],"Solution":{"Idea":{"Ar":"المشتقة الاتجاهية هي الضرب القياسي للتدرج بمتجه وحدة الاتجاه.","En":"The directional derivative is the gradient dotted with the unit direction vector."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"المشتقتان الجزئيتان هما $2x$ و$6y$؛ الاتجاه الموجب لمحور $x$ متجه وحدته $(1,0)$.","En":"The partial derivatives are $2x$ and $6y$; the positive x-direction has unit vector $(1,0)$."},{"Ar":"التدرج عند النقطة يساوي $(2,12)$، والجداء النقطي ينتقي المركبة الأولى.","En":"The gradient at the point is $(2,12)$; the dot product selects its first component."}],"Result":{"Ar":"$2$","En":"$2$"},"CommonError":{"Ar":"لا تستخدم معيار التدرج بدلاً من إسقاطه الاتجاهي.","En":"Do not use the gradient norm instead of its directional projection."},"FormulaLatex":"D_{\\mathbf u}f=\\nabla f\\cdot\\mathbf u,\\quad \\mathbf u=(1,0)","Substitution":{"Ar":"$(2,12)\\cdot(1,0)=2+0=2$","En":"$(2,12)\\cdot(1,0)=2+0=2$"},"Verification":{"Ar":"$\\lim_{h\\to0}\\frac{f(1+h,2)-f(1,2)}{h}=\\lim_{h\\to0}(2+h)=2$","En":"$\\lim_{h\\to0}\\frac{f(1+h,2)-f(1,2)}{h}=\\lim_{h\\to0}(2+h)=2$"}},"Distractors":[{"ErrorType":"","Reason":null,"Order":1},{"ErrorType":"misconception","Reason":{"Ar":"في الاتجاه $(1,0)$ تكون مساهمة المركبة الرأسية صفراً. القيمة $3$ لا تساوي المركبة الأفقية $2\\cdot1$؛ راجع حساب الإسقاط.","En":"In direction $(1,0)$ the vertical contribution is zero. The choice $3$ is not the horizontal component $2\\cdot1$; recheck the projection."},"Order":2},{"ErrorType":"misconception","Reason":{"Ar":"في الاتجاه $(1,0)$ تكون مساهمة المركبة الرأسية صفراً. القيمة $5$ لا تساوي المركبة الأفقية $2\\cdot1$؛ راجع حساب الإسقاط.","En":"In direction $(1,0)$ the vertical contribution is zero. The choice $5$ is not the horizontal component $2\\cdot1$; recheck the projection."},"Order":3},{"ErrorType":"misconception","Reason":{"Ar":"ألغى المركبتين رغم أن مركبة الاتجاه الأفقية تساوي واحداً.","En":"Cancels both components although the horizontal direction component is one."},"Order":4}]}$mw$,$mw$المشتقة الاتجاهية هي الضرب القياسي للتدرج بمتجه وحدة الاتجاه.

$D_{\mathbf u}f=\nabla f\cdot\mathbf u,\quad \mathbf u=(1,0)$

1. المشتقتان الجزئيتان هما $2x$ و$6y$؛ الاتجاه الموجب لمحور $x$ متجه وحدته $(1,0)$.

2. التدرج عند النقطة يساوي $(2,12)$، والجداء النقطي ينتقي المركبة الأولى.

$(2,12)\cdot(1,0)=2+0=2$

$2$ بلا وحدة قياس

$\lim_{h\to0}\frac{f(1+h,2)-f(1,2)}{h}=\lim_{h\to0}(2+h)=2$

لا تستخدم معيار التدرج بدلاً من إسقاطه الاتجاهي.$mw$,$mw$The directional derivative is the gradient dotted with the unit direction vector.

$D_{\mathbf u}f=\nabla f\cdot\mathbf u,\quad \mathbf u=(1,0)$

1. The partial derivatives are $2x$ and $6y$; the positive x-direction has unit vector $(1,0)$.

2. The gradient at the point is $(2,12)$; the dot product selects its first component.

$(2,12)\cdot(1,0)=2+0=2$

$2$ Dimensionless

$\lim_{h\to0}\frac{f(1+h,2)-f(1,2)}{h}=\lim_{h\to0}(2+h)=2$

Do not use the gradient norm instead of its directional projection.$mw$),
(538,332,$mw$AE798A24152038F1A7860A28F949D520FEC589A064658D79A92AAB58CC2CCC0A$mw$,$mw$d8da964957f105bd6345177dbf57df26$mw$,$mw$$mw$,$mw${"Id":332,"StageId":4,"CategoryId":14,"Points":15,"TitleAr":"ما أثر المصفوفة \\(\\begin{pmatrix}2&0\\\\0&4\\end{pmatrix}\\)؟","TitleEn":"Find trace of \\(\\begin{pmatrix}2&0\\\\0&4\\end{pmatrix}\\).","QuestionTextAr":"ما أثر المصفوفة \\(\\begin{pmatrix}2&0\\\\0&4\\end{pmatrix}\\)؟","QuestionTextEn":"Find trace of \\(\\begin{pmatrix}2&0\\\\0&4\\end{pmatrix}\\).","DetailedSolutionAr":"تعريف أثر المصفوفة المربعة tr(A): مجموع عناصر القطر الرئيسي من أعلى اليسار إلى أسفل اليمين. المصفوفة المعطاة قطرها الرئيسي 2 و4، لذا tr(A) = 2 + 4 = 6. لا نخلط بين الأثر والمحدد، فالعمليتان مختلفتان.","DetailedSolutionEn":"Trace of a square matrix is the sum of its main diagonal entries. Here the main diagonal contains 2 and 4, so tr(A) = 2 + 4 = 6. The trace is not the determinant.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":1317,"Order":1,"LatexCode":"4","IsCorrect":false},{"Id":1318,"Order":2,"LatexCode":"6","IsCorrect":true},{"Id":1319,"Order":3,"LatexCode":"7","IsCorrect":false},{"Id":1320,"Order":4,"LatexCode":"9","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"حدد عناصر القطر الرئيسي.","En":"Identify the main diagonal entries."},{"Ar":"اجمع عناصر القطر الرئيسي فقط.","En":"Sum only the main diagonal entries."}],"Title":{"Ar":"ما أثر المصفوفة \\(\\begin{pmatrix}2&0\\\\0&4\\end{pmatrix}\\)؟","En":"Find trace of \\(\\begin{pmatrix}2&0\\\\0&4\\end{pmatrix}\\)."},"Points":15,"Options":[{"Reason":{"Ar":"حسب عنصراً واحداً من القطر وأهمل الآخر.","En":"Counts only one diagonal entry and omits the other."},"ErrorType":"misconception","IsCorrect":false,"LatexCode":"4"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"6"},{"Reason":{"Ar":"الأثر يضم العنصرين $2$ و$4$ فقط. القيمة $7$ أكبر من مجموعهما بمقدار $1$؛ راجع الجمع دون إدخال عناصر إضافية.","En":"Trace uses only $2$ and $4$. The choice $7$ is 1 above their sum; recheck the addition without introducing extra entries."},"ErrorType":"misconception","IsCorrect":false,"LatexCode":"7"},{"Reason":{"Ar":"الأثر يضم العنصرين $2$ و$4$ فقط. القيمة $9$ أكبر من مجموعهما بمقدار $3$؛ راجع الجمع دون إدخال عناصر إضافية.","En":"Trace uses only $2$ and $4$. The choice $9$ is 3 above their sum; recheck the addition without introducing extra entries."},"ErrorType":"misconception","IsCorrect":false,"LatexCode":"9"}],"StageId":4,"Question":{"Ar":"ما أثر المصفوفة \\(\\begin{pmatrix}2&0\\\\0&4\\end{pmatrix}\\)؟","En":"Find trace of \\(\\begin{pmatrix}2&0\\\\0&4\\end{pmatrix}\\)."},"Solution":{"Idea":{"Ar":"أثر المصفوفة المربعة مجموع عناصر قطرها الرئيسي.","En":"The trace of a square matrix is the sum of its main diagonal entries."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"عنصرا القطر الرئيسي هما $2$ و$4$؛ العنصران خارج القطر صفران.","En":"The main diagonal entries are $2$ and $4$; the off-diagonal entries are zero."},{"Ar":"الأثر هو مجموع عنصري القطر وليس حاصل ضربهما.","En":"The trace is their sum, not their product."}],"Result":{"Ar":"$6$","En":"$6$"},"CommonError":{"Ar":"لا تخلط الأثر بالمحدد أو بجميع عناصر المصفوفة.","En":"Do not confuse trace with determinant or the sum of all entries."},"FormulaLatex":"\\operatorname{tr}(A)=a_{11}+a_{22}","Substitution":{"Ar":"$2+4=6$","En":"$2+4=6$"},"Verification":{"Ar":"$\\operatorname{tr}(A)=4+2=6$","En":"$\\operatorname{tr}(A)=4+2=6$"}},"TrackIds":[14,20],"CategoryId":14,"PrimarySkillId":64,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"حدد عناصر القطر الرئيسي.","En":"Identify the main diagonal entries."},{"Ar":"اجمع عناصر القطر الرئيسي فقط.","En":"Sum only the main diagonal entries."}],"Solution":{"Idea":{"Ar":"أثر المصفوفة المربعة مجموع عناصر قطرها الرئيسي.","En":"The trace of a square matrix is the sum of its main diagonal entries."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"عنصرا القطر الرئيسي هما $2$ و$4$؛ العنصران خارج القطر صفران.","En":"The main diagonal entries are $2$ and $4$; the off-diagonal entries are zero."},{"Ar":"الأثر هو مجموع عنصري القطر وليس حاصل ضربهما.","En":"The trace is their sum, not their product."}],"Result":{"Ar":"$6$","En":"$6$"},"CommonError":{"Ar":"لا تخلط الأثر بالمحدد أو بجميع عناصر المصفوفة.","En":"Do not confuse trace with determinant or the sum of all entries."},"FormulaLatex":"\\operatorname{tr}(A)=a_{11}+a_{22}","Substitution":{"Ar":"$2+4=6$","En":"$2+4=6$"},"Verification":{"Ar":"$\\operatorname{tr}(A)=4+2=6$","En":"$\\operatorname{tr}(A)=4+2=6$"}},"Distractors":[{"ErrorType":"misconception","Reason":{"Ar":"حسب عنصراً واحداً من القطر وأهمل الآخر.","En":"Counts only one diagonal entry and omits the other."},"Order":1},{"ErrorType":"","Reason":null,"Order":2},{"ErrorType":"misconception","Reason":{"Ar":"الأثر يضم العنصرين $2$ و$4$ فقط. القيمة $7$ أكبر من مجموعهما بمقدار $1$؛ راجع الجمع دون إدخال عناصر إضافية.","En":"Trace uses only $2$ and $4$. The choice $7$ is 1 above their sum; recheck the addition without introducing extra entries."},"Order":3},{"ErrorType":"misconception","Reason":{"Ar":"الأثر يضم العنصرين $2$ و$4$ فقط. القيمة $9$ أكبر من مجموعهما بمقدار $3$؛ راجع الجمع دون إدخال عناصر إضافية.","En":"Trace uses only $2$ and $4$. The choice $9$ is 3 above their sum; recheck the addition without introducing extra entries."},"Order":4}]}$mw$,$mw$أثر المصفوفة المربعة مجموع عناصر قطرها الرئيسي.

$\operatorname{tr}(A)=a_{11}+a_{22}$

1. عنصرا القطر الرئيسي هما $2$ و$4$؛ العنصران خارج القطر صفران.

2. الأثر هو مجموع عنصري القطر وليس حاصل ضربهما.

$2+4=6$

$6$ بلا وحدة قياس

$\operatorname{tr}(A)=4+2=6$

لا تخلط الأثر بالمحدد أو بجميع عناصر المصفوفة.$mw$,$mw$The trace of a square matrix is the sum of its main diagonal entries.

$\operatorname{tr}(A)=a_{11}+a_{22}$

1. The main diagonal entries are $2$ and $4$; the off-diagonal entries are zero.

2. The trace is their sum, not their product.

$2+4=6$

$6$ Dimensionless

$\operatorname{tr}(A)=4+2=6$

Do not confuse trace with determinant or the sum of all entries.$mw$),
(539,333,$mw$D14C21C104B8C3457BDCA0DFE2A4DFFA2456C2671F7DACA63D7120DE5718C86D$mw$,$mw$52094cc89b2d82b8202a56f7fd77a3ed$mw$,$mw$$mw$,$mw${"Id":333,"StageId":4,"CategoryId":14,"Points":15,"TitleAr":"اضرب المتجه (3،4) بالعدد 2.","TitleEn":"Multiply vector (3,4) by scalar 2.","QuestionTextAr":"اضرب المتجه (3،4) بالعدد 2.","QuestionTextEn":"Multiply vector (3,4) by scalar 2.","DetailedSolutionAr":"قانون ضرب المتجه بعدد حقيقي: k(أ،ب) = (kأ، kب). عند ضرب المتجه (3،4) في العدد 2 نضرب كل مركبة مستقلة: (2×3، 2×4) = (6،8). لا نجمع المركبتين، لأن الناتج متجه ذو مركبتين.","DetailedSolutionEn":"Scalar-vector multiplication: k(a,b)=(ka,kb). Multiplying (3,4) by 2 scales each component: (2×3,2×4)=(6,8). The result remains a two-component vector.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":1321,"Order":1,"LatexCode":"(6,8)","IsCorrect":true},{"Id":1322,"Order":2,"LatexCode":"(5,6)","IsCorrect":false},{"Id":1323,"Order":3,"LatexCode":"(8,6)","IsCorrect":false},{"Id":1324,"Order":4,"LatexCode":"(3,8)","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"حدد العامل العددي والمركبتين.","En":"Identify the scalar and the two components."},{"Ar":"اضرب كل مركبة بالعامل نفسه مع الحفاظ على الترتيب.","En":"Multiply each component by the scalar, preserving order."}],"Title":{"Ar":"اضرب المتجه (3،4) بالعدد 2.","En":"Multiply vector (3,4) by scalar 2."},"Points":15,"Options":[{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"(6,8)"},{"Reason":{"Ar":"جمع العامل مع المركبتين بدلاً من الضرب.","En":"Adds the scalar to each component instead of multiplying."},"ErrorType":"misconception","IsCorrect":false,"LatexCode":"(5,6)"},{"Reason":{"Ar":"بدّل ترتيب المركبتين بعد ضربهما.","En":"Reverses the components after scaling."},"ErrorType":"misconception","IsCorrect":false,"LatexCode":"(8,6)"},{"Reason":{"Ar":"ضرب المركبة الثانية فقط وأبقى الأولى دون تغيير.","En":"Scales only the second component and leaves the first unchanged."},"ErrorType":"misconception","IsCorrect":false,"LatexCode":"(3,8)"}],"StageId":4,"Question":{"Ar":"اضرب المتجه (3،4) بالعدد 2.","En":"Multiply vector (3,4) by scalar 2."},"Solution":{"Idea":{"Ar":"الضرب بعدد حقيقي يضرب كل مركبة من المتجه بالعدد نفسه.","En":"Scalar multiplication scales each vector component by the same factor."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"نضرب المركبة الأولى $3$ في العامل $2$ فنحصل على $6$.","En":"Multiply first component $3$ by scalar $2$ to get $6$."},{"Ar":"نضرب المركبة الثانية $4$ في العامل نفسه فنحصل على $8$، ونحافظ على ترتيب المركبتين.","En":"Multiply second component $4$ by the same scalar to get $8$, preserving order."}],"Result":{"Ar":"$(6,8)$","En":"$(6,8)$"},"CommonError":{"Ar":"لا تضف العامل إلى المركبات أو تضرب مركبة واحدة فقط.","En":"Do not add the scalar or scale only one component."},"FormulaLatex":"k(a,b)=(ka,kb)","Substitution":{"Ar":"$2(3,4)=(2\\cdot3,2\\cdot4)=(6,8)$","En":"$2(3,4)=(2\\cdot3,2\\cdot4)=(6,8)$"},"Verification":{"Ar":"$(6/2,8/2)=(3,4)$","En":"$(6/2,8/2)=(3,4)$"}},"TrackIds":[14,20],"CategoryId":14,"PrimarySkillId":65,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"حدد العامل العددي والمركبتين.","En":"Identify the scalar and the two components."},{"Ar":"اضرب كل مركبة بالعامل نفسه مع الحفاظ على الترتيب.","En":"Multiply each component by the scalar, preserving order."}],"Solution":{"Idea":{"Ar":"الضرب بعدد حقيقي يضرب كل مركبة من المتجه بالعدد نفسه.","En":"Scalar multiplication scales each vector component by the same factor."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"نضرب المركبة الأولى $3$ في العامل $2$ فنحصل على $6$.","En":"Multiply first component $3$ by scalar $2$ to get $6$."},{"Ar":"نضرب المركبة الثانية $4$ في العامل نفسه فنحصل على $8$، ونحافظ على ترتيب المركبتين.","En":"Multiply second component $4$ by the same scalar to get $8$, preserving order."}],"Result":{"Ar":"$(6,8)$","En":"$(6,8)$"},"CommonError":{"Ar":"لا تضف العامل إلى المركبات أو تضرب مركبة واحدة فقط.","En":"Do not add the scalar or scale only one component."},"FormulaLatex":"k(a,b)=(ka,kb)","Substitution":{"Ar":"$2(3,4)=(2\\cdot3,2\\cdot4)=(6,8)$","En":"$2(3,4)=(2\\cdot3,2\\cdot4)=(6,8)$"},"Verification":{"Ar":"$(6/2,8/2)=(3,4)$","En":"$(6/2,8/2)=(3,4)$"}},"Distractors":[{"ErrorType":"","Reason":null,"Order":1},{"ErrorType":"misconception","Reason":{"Ar":"جمع العامل مع المركبتين بدلاً من الضرب.","En":"Adds the scalar to each component instead of multiplying."},"Order":2},{"ErrorType":"misconception","Reason":{"Ar":"بدّل ترتيب المركبتين بعد ضربهما.","En":"Reverses the components after scaling."},"Order":3},{"ErrorType":"misconception","Reason":{"Ar":"ضرب المركبة الثانية فقط وأبقى الأولى دون تغيير.","En":"Scales only the second component and leaves the first unchanged."},"Order":4}]}$mw$,$mw$الضرب بعدد حقيقي يضرب كل مركبة من المتجه بالعدد نفسه.

$k(a,b)=(ka,kb)$

1. نضرب المركبة الأولى $3$ في العامل $2$ فنحصل على $6$.

2. نضرب المركبة الثانية $4$ في العامل نفسه فنحصل على $8$، ونحافظ على ترتيب المركبتين.

$2(3,4)=(2\cdot3,2\cdot4)=(6,8)$

$(6,8)$ بلا وحدة قياس

$(6/2,8/2)=(3,4)$

لا تضف العامل إلى المركبات أو تضرب مركبة واحدة فقط.$mw$,$mw$Scalar multiplication scales each vector component by the same factor.

$k(a,b)=(ka,kb)$

1. Multiply first component $3$ by scalar $2$ to get $6$.

2. Multiply second component $4$ by the same scalar to get $8$, preserving order.

$2(3,4)=(2\cdot3,2\cdot4)=(6,8)$

$(6,8)$ Dimensionless

$(6/2,8/2)=(3,4)$

Do not add the scalar or scale only one component.$mw$),
(540,334,$mw$773162CE32E148D402E26B4EF39E9121FC6C9EE15B303DF49631D897CC7A4AC1$mw$,$mw$873188f9b63d05ea597235312c3205ba$mw$,$mw$$mw$,$mw${"Id":334,"StageId":4,"CategoryId":14,"Points":15,"TitleAr":"ما محدد \\(\\begin{pmatrix}2&3\\\\0&5\\end{pmatrix}\\)؟","TitleEn":"Find determinant of \\(\\begin{pmatrix}2&3\\\\0&5\\end{pmatrix}\\).","QuestionTextAr":"ما محدد \\(\\begin{pmatrix}2&3\\\\0&5\\end{pmatrix}\\)؟","QuestionTextEn":"Find determinant of \\(\\begin{pmatrix}2&3\\\\0&5\\end{pmatrix}\\).","DetailedSolutionAr":"قاعدة المحدد للمصفوفة المثلثية: حاصل ضرب عناصر القطر الرئيسي. للمصفوفة [[2،3],[0،5]] نحسب det = 2×5 − 3×0 = 2×5 = 10. وجود صفر تحت القطر يبسط القانون، فلا تسهم القيمة 3 في الحد المطروح.","DetailedSolutionEn":"Triangular matrix determinant equals the product of the main diagonal entries. For [[2,3],[0,5]], det=2×5−3×0=2×5=10. The zero below the diagonal removes the second product.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":1325,"Order":1,"LatexCode":"11","IsCorrect":false},{"Id":1326,"Order":2,"LatexCode":"13","IsCorrect":false},{"Id":1327,"Order":3,"LatexCode":"8","IsCorrect":false},{"Id":1328,"Order":4,"LatexCode":"10","IsCorrect":true}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"حدد القطرين في المصفوفة.","En":"Identify the two diagonals."},{"Ar":"احسب حاصل ضرب عناصر كل قطر ثم اطرح جداء القطر الثانوي.","En":"Compute both diagonal products and subtract the second from the first."}],"Title":{"Ar":"ما محدد \\(\\begin{pmatrix}2&3\\\\0&5\\end{pmatrix}\\)؟","En":"Find determinant of \\(\\begin{pmatrix}2&3\\\\0&5\\end{pmatrix}\\)."},"Points":15,"Options":[{"Reason":{"Ar":"لأن المصفوفة مثلثية، لا يؤثر العنصر $3$ خارج القطر على المحدد. القيمة $11$ تختلف عن جداء القطر بمقدار $1$؛ راجع ضرب العنصرين.","En":"Because the matrix is triangular, off-diagonal entry $3$ does not affect the determinant. The choice $11$ differs from the diagonal product by $1$; recheck the multiplication."},"ErrorType":"misconception","IsCorrect":false,"LatexCode":"11"},{"Reason":{"Ar":"لأن المصفوفة مثلثية، لا يؤثر العنصر $3$ خارج القطر على المحدد. القيمة $13$ تختلف عن جداء القطر بمقدار $3$؛ راجع ضرب العنصرين.","En":"Because the matrix is triangular, off-diagonal entry $3$ does not affect the determinant. The choice $13$ differs from the diagonal product by $3$; recheck the multiplication."},"ErrorType":"misconception","IsCorrect":false,"LatexCode":"13"},{"Reason":{"Ar":"لأن المصفوفة مثلثية، لا يؤثر العنصر $3$ خارج القطر على المحدد. القيمة $8$ تختلف عن جداء القطر بمقدار $-2$؛ راجع ضرب العنصرين.","En":"Because the matrix is triangular, off-diagonal entry $3$ does not affect the determinant. The choice $8$ differs from the diagonal product by $-2$; recheck the multiplication."},"ErrorType":"misconception","IsCorrect":false,"LatexCode":"8"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"10"}],"StageId":4,"Question":{"Ar":"ما محدد \\(\\begin{pmatrix}2&3\\\\0&5\\end{pmatrix}\\)؟","En":"Find determinant of \\(\\begin{pmatrix}2&3\\\\0&5\\end{pmatrix}\\)."},"Solution":{"Idea":{"Ar":"محدد المصفوفة الثنائية هو جداء القطر الرئيسي ناقص جداء القطر الثانوي.","En":"The determinant of a two-by-two matrix is the main diagonal product minus the other diagonal product."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"جداء القطر الرئيسي هو $2\\cdot5=10$.","En":"The main diagonal product is $2\\cdot5=10$."},{"Ar":"جداء القطر الآخر هو $3\\cdot0=0$؛ نطرح هذا الجداء من الأول.","En":"The other diagonal product is $3\\cdot0=0$; subtract it from the first."}],"Result":{"Ar":"$10$","En":"$10$"},"CommonError":{"Ar":"لا تجمع الجداءين أو تعكس ترتيب الطرح.","En":"Do not add the products or reverse subtraction."},"FormulaLatex":"\\det\\begin{pmatrix}a&b\\\\c&d\\end{pmatrix}=ad-bc","Substitution":{"Ar":"$2\\cdot5-3\\cdot0=10$","En":"$2\\cdot5-3\\cdot0=10$"},"Verification":{"Ar":"المصفوفة مثلثية علوية، ومحدد المصفوفة المثلثية حاصل ضرب عناصر قطرها الرئيسي، وهو 10.","En":"The matrix is upper triangular; its determinant is the product of diagonal entries, 10."}},"TrackIds":[14,20],"CategoryId":14,"PrimarySkillId":61,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"حدد القطرين في المصفوفة.","En":"Identify the two diagonals."},{"Ar":"احسب حاصل ضرب عناصر كل قطر ثم اطرح جداء القطر الثانوي.","En":"Compute both diagonal products and subtract the second from the first."}],"Solution":{"Idea":{"Ar":"محدد المصفوفة الثنائية هو جداء القطر الرئيسي ناقص جداء القطر الثانوي.","En":"The determinant of a two-by-two matrix is the main diagonal product minus the other diagonal product."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"جداء القطر الرئيسي هو $2\\cdot5=10$.","En":"The main diagonal product is $2\\cdot5=10$."},{"Ar":"جداء القطر الآخر هو $3\\cdot0=0$؛ نطرح هذا الجداء من الأول.","En":"The other diagonal product is $3\\cdot0=0$; subtract it from the first."}],"Result":{"Ar":"$10$","En":"$10$"},"CommonError":{"Ar":"لا تجمع الجداءين أو تعكس ترتيب الطرح.","En":"Do not add the products or reverse subtraction."},"FormulaLatex":"\\det\\begin{pmatrix}a&b\\\\c&d\\end{pmatrix}=ad-bc","Substitution":{"Ar":"$2\\cdot5-3\\cdot0=10$","En":"$2\\cdot5-3\\cdot0=10$"},"Verification":{"Ar":"المصفوفة مثلثية علوية، ومحدد المصفوفة المثلثية حاصل ضرب عناصر قطرها الرئيسي، وهو 10.","En":"The matrix is upper triangular; its determinant is the product of diagonal entries, 10."}},"Distractors":[{"ErrorType":"misconception","Reason":{"Ar":"لأن المصفوفة مثلثية، لا يؤثر العنصر $3$ خارج القطر على المحدد. القيمة $11$ تختلف عن جداء القطر بمقدار $1$؛ راجع ضرب العنصرين.","En":"Because the matrix is triangular, off-diagonal entry $3$ does not affect the determinant. The choice $11$ differs from the diagonal product by $1$; recheck the multiplication."},"Order":1},{"ErrorType":"misconception","Reason":{"Ar":"لأن المصفوفة مثلثية، لا يؤثر العنصر $3$ خارج القطر على المحدد. القيمة $13$ تختلف عن جداء القطر بمقدار $3$؛ راجع ضرب العنصرين.","En":"Because the matrix is triangular, off-diagonal entry $3$ does not affect the determinant. The choice $13$ differs from the diagonal product by $3$; recheck the multiplication."},"Order":2},{"ErrorType":"misconception","Reason":{"Ar":"لأن المصفوفة مثلثية، لا يؤثر العنصر $3$ خارج القطر على المحدد. القيمة $8$ تختلف عن جداء القطر بمقدار $-2$؛ راجع ضرب العنصرين.","En":"Because the matrix is triangular, off-diagonal entry $3$ does not affect the determinant. The choice $8$ differs from the diagonal product by $-2$; recheck the multiplication."},"Order":3},{"ErrorType":"","Reason":null,"Order":4}]}$mw$,$mw$محدد المصفوفة الثنائية هو جداء القطر الرئيسي ناقص جداء القطر الثانوي.

$\det\begin{pmatrix}a&b\\c&d\end{pmatrix}=ad-bc$

1. جداء القطر الرئيسي هو $2\cdot5=10$.

2. جداء القطر الآخر هو $3\cdot0=0$؛ نطرح هذا الجداء من الأول.

$2\cdot5-3\cdot0=10$

$10$ بلا وحدة قياس

المصفوفة مثلثية علوية، ومحدد المصفوفة المثلثية حاصل ضرب عناصر قطرها الرئيسي، وهو 10.

لا تجمع الجداءين أو تعكس ترتيب الطرح.$mw$,$mw$The determinant of a two-by-two matrix is the main diagonal product minus the other diagonal product.

$\det\begin{pmatrix}a&b\\c&d\end{pmatrix}=ad-bc$

1. The main diagonal product is $2\cdot5=10$.

2. The other diagonal product is $3\cdot0=0$; subtract it from the first.

$2\cdot5-3\cdot0=10$

$10$ Dimensionless

The matrix is upper triangular; its determinant is the product of diagonal entries, 10.

Do not add the products or reverse subtraction.$mw$),
(541,335,$mw$2FEC0F4526D8EE3BA0CAC812AC369379346C45FBB1FA189F8E3B7E381F9B5325$mw$,$mw$2cb7916a1c4de5505177c48ef3ecbfab$mw$,$mw$$mw$,$mw${"Id":335,"StageId":4,"CategoryId":15,"Points":15,"TitleAr":"إذا \\(y'=3\\) و\\(y(0)=2\\)، أوجد \\(y(4)\\).","TitleEn":"Given \\(y'=3\\), \\(y(0)=2\\), find \\(y(4)\\).","QuestionTextAr":"إذا \\(y'=3\\) و\\(y(0)=2\\)، أوجد \\(y(4)\\).","QuestionTextEn":"Given \\(y'=3\\), \\(y(0)=2\\), find \\(y(4)\\).","DetailedSolutionAr":"قاعدة التكامل: إذا كانت y′ = 3 ثابتة، فالدالة y(x) = 3x + C. باستخدام y(0) = 2 نحصل على C = 2. بالتعويض عند x = 4: ‏y(4) = 3 × 4 + 2 = 14. التحقق: مشتقة 3x + 2 هي 3، ويحقق الشرط الابتدائي.","DetailedSolutionEn":"Integration rule: If y′ = 3 is constant, then y(x) = 3x + C. From y(0) = 2, we obtain C = 2. Evaluate at x = 4: y(4) = 3 × 4 + 2 = 14. The derivative is 3, and y(0) agrees with the initial value.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":1329,"Order":1,"LatexCode":"14","IsCorrect":true},{"Id":1330,"Order":2,"LatexCode":"15","IsCorrect":false},{"Id":1331,"Order":3,"LatexCode":"17","IsCorrect":false},{"Id":1332,"Order":4,"LatexCode":"12","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"ابدأ بتكامل الطرف الأيمن.","En":"Start by integrating the right-hand side."},{"Ar":"استعمل قيمة y عند الصفر لتحديد الثابت ثم عوض المدخل المطلوب.","En":"Use the value at zero to determine the constant and evaluate the requested input."}],"Title":{"Ar":"إذا \\(y'=3\\) و\\(y(0)=2\\)، أوجد \\(y(4)\\).","En":"Given \\(y'=3\\), \\(y(0)=2\\), find \\(y(4)\\)."},"Points":15,"Options":[{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"14"},{"Reason":{"Ar":"بعد تحديد الجزء المتغير $12$، فإن اختيار $15$ يستلزم قيمة ابتدائية $3$ بدلاً من $2$، فلا يحقق الشرط.","En":"With variable part $12$, choice $15$ would require initial value $3$ rather than $2$, violating the condition."},"ErrorType":"misconception","IsCorrect":false,"LatexCode":"15"},{"Reason":{"Ar":"بعد تحديد الجزء المتغير $12$، فإن اختيار $17$ يستلزم قيمة ابتدائية $5$ بدلاً من $2$، فلا يحقق الشرط.","En":"With variable part $12$, choice $17$ would require initial value $5$ rather than $2$, violating the condition."},"ErrorType":"misconception","IsCorrect":false,"LatexCode":"17"},{"Reason":{"Ar":"أهمل ثابت التكامل $2$ المستنتج من قيمة الدالة عند الصفر.","En":"Omits integration constant $2$ determined by the value at zero."},"ErrorType":"misconception","IsCorrect":false,"LatexCode":"12"}],"StageId":4,"Question":{"Ar":"إذا \\(y'=3\\) و\\(y(0)=2\\)، أوجد \\(y(4)\\).","En":"Given \\(y'=3\\), \\(y(0)=2\\), find \\(y(4)\\)."},"Solution":{"Idea":{"Ar":"نستخدم التكامل لاستعادة الدالة من مشتقتها، والشرط الابتدائي يحدد الثابت.","En":"Integrate to recover the function; the initial condition determines the constant."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"نكامل الطرف الأيمن فنحصل على $y=3x+C$.","En":"Integrate the right-hand side to obtain $y=3x+C$."},{"Ar":"من $y(0)=2$ نجد $C=2$، فنعوض $x=4$ في الحل.","En":"From $y(0)=2$ we get $C=2$, then substitute $x=4$."}],"Result":{"Ar":"$14$","En":"$14$"},"CommonError":{"Ar":"لا تنس ثابت التكامل أو التعويض بالشرط الابتدائي.","En":"Do not omit the integration constant or initial condition."},"FormulaLatex":"y(x)=y(0)+\\int_0^x g(t)\\,dt","Substitution":{"Ar":"$y(4)=3(4)+2=12+2=14$","En":"$y(4)=3(4)+2=12+2=14$"},"Verification":{"Ar":"$(3x+2)'=3,\\quad y(0)=2$","En":"$(3x+2)'=3,\\quad y(0)=2$"}},"TrackIds":[15,21],"CategoryId":15,"PrimarySkillId":68,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"ابدأ بتكامل الطرف الأيمن.","En":"Start by integrating the right-hand side."},{"Ar":"استعمل قيمة y عند الصفر لتحديد الثابت ثم عوض المدخل المطلوب.","En":"Use the value at zero to determine the constant and evaluate the requested input."}],"Solution":{"Idea":{"Ar":"نستخدم التكامل لاستعادة الدالة من مشتقتها، والشرط الابتدائي يحدد الثابت.","En":"Integrate to recover the function; the initial condition determines the constant."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"نكامل الطرف الأيمن فنحصل على $y=3x+C$.","En":"Integrate the right-hand side to obtain $y=3x+C$."},{"Ar":"من $y(0)=2$ نجد $C=2$، فنعوض $x=4$ في الحل.","En":"From $y(0)=2$ we get $C=2$, then substitute $x=4$."}],"Result":{"Ar":"$14$","En":"$14$"},"CommonError":{"Ar":"لا تنس ثابت التكامل أو التعويض بالشرط الابتدائي.","En":"Do not omit the integration constant or initial condition."},"FormulaLatex":"y(x)=y(0)+\\int_0^x g(t)\\,dt","Substitution":{"Ar":"$y(4)=3(4)+2=12+2=14$","En":"$y(4)=3(4)+2=12+2=14$"},"Verification":{"Ar":"$(3x+2)'=3,\\quad y(0)=2$","En":"$(3x+2)'=3,\\quad y(0)=2$"}},"Distractors":[{"ErrorType":"","Reason":null,"Order":1},{"ErrorType":"misconception","Reason":{"Ar":"بعد تحديد الجزء المتغير $12$، فإن اختيار $15$ يستلزم قيمة ابتدائية $3$ بدلاً من $2$، فلا يحقق الشرط.","En":"With variable part $12$, choice $15$ would require initial value $3$ rather than $2$, violating the condition."},"Order":2},{"ErrorType":"misconception","Reason":{"Ar":"بعد تحديد الجزء المتغير $12$، فإن اختيار $17$ يستلزم قيمة ابتدائية $5$ بدلاً من $2$، فلا يحقق الشرط.","En":"With variable part $12$, choice $17$ would require initial value $5$ rather than $2$, violating the condition."},"Order":3},{"ErrorType":"misconception","Reason":{"Ar":"أهمل ثابت التكامل $2$ المستنتج من قيمة الدالة عند الصفر.","En":"Omits integration constant $2$ determined by the value at zero."},"Order":4}]}$mw$,$mw$نستخدم التكامل لاستعادة الدالة من مشتقتها، والشرط الابتدائي يحدد الثابت.

$y(x)=y(0)+\int_0^x g(t)\,dt$

1. نكامل الطرف الأيمن فنحصل على $y=3x+C$.

2. من $y(0)=2$ نجد $C=2$، فنعوض $x=4$ في الحل.

$y(4)=3(4)+2=12+2=14$

$14$ بلا وحدة قياس

$(3x+2)'=3,\quad y(0)=2$

لا تنس ثابت التكامل أو التعويض بالشرط الابتدائي.$mw$,$mw$Integrate to recover the function; the initial condition determines the constant.

$y(x)=y(0)+\int_0^x g(t)\,dt$

1. Integrate the right-hand side to obtain $y=3x+C$.

2. From $y(0)=2$ we get $C=2$, then substitute $x=4$.

$y(4)=3(4)+2=12+2=14$

$14$ Dimensionless

$(3x+2)'=3,\quad y(0)=2$

Do not omit the integration constant or initial condition.$mw$),
(542,336,$mw$4E4C918CAEACEE1AF5079A477711DB35EA83857F9FDF850E98D49AFFE799B989$mw$,$mw$27ef0b9bc5ef4a9967cc436af0ae2a0e$mw$,$mw$$mw$,$mw${"Id":336,"StageId":4,"CategoryId":15,"Points":15,"TitleAr":"إذا \\(y''=0\\) و\\(y'(0)=2\\) و\\(y(0)=3\\)، أوجد \\(y(3)\\).","TitleEn":"Given \\(y''=0\\), \\(y'(0)=2\\), \\(y(0)=3\\), find \\(y(3)\\).","QuestionTextAr":"إذا \\(y''=0\\) و\\(y'(0)=2\\) و\\(y(0)=3\\)، أوجد \\(y(3)\\).","QuestionTextEn":"Given \\(y''=0\\), \\(y'(0)=2\\), \\(y(0)=3\\), find \\(y(3)\\).","DetailedSolutionAr":"القانون المستخدم: إذا كانت المشتقة الثانية y″ = 0، فالمشتقة الأولى ثابتة y′ = C₁ والدالة خطية y = C₁x + C₂. من y′(0) = 2 نجد C₁ = 2، ومن y(0) = 3 نجد C₂ = 3. إذن y(3) = 2 × 3 + 3 = 9.","DetailedSolutionEn":"Rule used: If y″ = 0, then y′ is constant and y(x) = C₁x + C₂. The conditions y′(0) = 2 and y(0) = 3 yield C₁ = 2, C₂ = 3. Thus y(3) = 2 × 3 + 3 = 9. Differentiate twice to check that y″ = 0.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":1333,"Order":1,"LatexCode":"10","IsCorrect":false},{"Id":1334,"Order":2,"LatexCode":"12","IsCorrect":false},{"Id":1335,"Order":3,"LatexCode":"7","IsCorrect":false},{"Id":1336,"Order":4,"LatexCode":"9","IsCorrect":true}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"تحتاج إلى تكاملين لأن المعادلة من الرتبة الثانية.","En":"Two integrations are needed because the equation is second order."},{"Ar":"حدد ثابت كل تكامل باستعمال الشرط الابتدائي الموافق له.","En":"Determine each integration constant using the corresponding initial condition."}],"Title":{"Ar":"إذا \\(y''=0\\) و\\(y'(0)=2\\) و\\(y(0)=3\\)، أوجد \\(y(3)\\).","En":"Given \\(y''=0\\), \\(y'(0)=2\\), \\(y(0)=3\\), find \\(y(3)\\)."},"Points":15,"Options":[{"Reason":{"Ar":"بعد تحديد الجزء المتغير $6$، فإن اختيار $10$ يستلزم قيمة ابتدائية $4$ بدلاً من $3$، فلا يحقق الشرط.","En":"With variable part $6$, choice $10$ would require initial value $4$ rather than $3$, violating the condition."},"ErrorType":"misconception","IsCorrect":false,"LatexCode":"10"},{"Reason":{"Ar":"بعد تحديد الجزء المتغير $6$، فإن اختيار $12$ يستلزم قيمة ابتدائية $6$ بدلاً من $3$، فلا يحقق الشرط.","En":"With variable part $6$, choice $12$ would require initial value $6$ rather than $3$, violating the condition."},"ErrorType":"misconception","IsCorrect":false,"LatexCode":"12"},{"Reason":{"Ar":"بعد تحديد الجزء المتغير $6$، فإن اختيار $7$ يستلزم قيمة ابتدائية $1$ بدلاً من $3$، فلا يحقق الشرط.","En":"With variable part $6$, choice $7$ would require initial value $1$ rather than $3$, violating the condition."},"ErrorType":"misconception","IsCorrect":false,"LatexCode":"7"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"9"}],"StageId":4,"Question":{"Ar":"إذا \\(y''=0\\) و\\(y'(0)=2\\) و\\(y(0)=3\\)، أوجد \\(y(3)\\).","En":"Given \\(y''=0\\), \\(y'(0)=2\\), \\(y(0)=3\\), find \\(y(3)\\)."},"Solution":{"Idea":{"Ar":"تكامل المشتقة الثانية الصفرية مرتين يعطي دالة خطية بثابتين.","En":"Integrating a zero second derivative twice gives a linear function with two constants."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"بتكامل $y''=0$ نجد أن $y'$ ثابت، ومن الشرط الابتدائي $y'(0)=2$ يكون $y'=2$.","En":"Integrate $y''=0$ to obtain constant $y'$; the condition $y'(0)=2$ gives $y'=2$."},{"Ar":"نكامل مرة ثانية: $y=2x+C_2$، ثم نطبق $y(0)=3$ لتحديد الثابت.","En":"Integrate again: $y=2x+C_2$, then use $y(0)=3$ to fix the constant."}],"Result":{"Ar":"$9$","En":"$9$"},"CommonError":{"Ar":"لا تخلط شرط المشتقة بشرط الدالة.","En":"Do not confuse the derivative condition with the function condition."},"FormulaLatex":"y''=0\\Rightarrow y'=C_1\\Rightarrow y=C_1x+C_2","Substitution":{"Ar":"$y(3)=2(3)+3=6+3=9$","En":"$y(3)=2(3)+3=6+3=9$"},"Verification":{"Ar":"$(2x+3)''=0,\\quad y'(0)=2,\\quad y(0)=3$","En":"$(2x+3)''=0,\\quad y'(0)=2,\\quad y(0)=3$"}},"TrackIds":[15,21],"CategoryId":15,"PrimarySkillId":69,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"تحتاج إلى تكاملين لأن المعادلة من الرتبة الثانية.","En":"Two integrations are needed because the equation is second order."},{"Ar":"حدد ثابت كل تكامل باستعمال الشرط الابتدائي الموافق له.","En":"Determine each integration constant using the corresponding initial condition."}],"Solution":{"Idea":{"Ar":"تكامل المشتقة الثانية الصفرية مرتين يعطي دالة خطية بثابتين.","En":"Integrating a zero second derivative twice gives a linear function with two constants."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"بتكامل $y''=0$ نجد أن $y'$ ثابت، ومن الشرط الابتدائي $y'(0)=2$ يكون $y'=2$.","En":"Integrate $y''=0$ to obtain constant $y'$; the condition $y'(0)=2$ gives $y'=2$."},{"Ar":"نكامل مرة ثانية: $y=2x+C_2$، ثم نطبق $y(0)=3$ لتحديد الثابت.","En":"Integrate again: $y=2x+C_2$, then use $y(0)=3$ to fix the constant."}],"Result":{"Ar":"$9$","En":"$9$"},"CommonError":{"Ar":"لا تخلط شرط المشتقة بشرط الدالة.","En":"Do not confuse the derivative condition with the function condition."},"FormulaLatex":"y''=0\\Rightarrow y'=C_1\\Rightarrow y=C_1x+C_2","Substitution":{"Ar":"$y(3)=2(3)+3=6+3=9$","En":"$y(3)=2(3)+3=6+3=9$"},"Verification":{"Ar":"$(2x+3)''=0,\\quad y'(0)=2,\\quad y(0)=3$","En":"$(2x+3)''=0,\\quad y'(0)=2,\\quad y(0)=3$"}},"Distractors":[{"ErrorType":"misconception","Reason":{"Ar":"بعد تحديد الجزء المتغير $6$، فإن اختيار $10$ يستلزم قيمة ابتدائية $4$ بدلاً من $3$، فلا يحقق الشرط.","En":"With variable part $6$, choice $10$ would require initial value $4$ rather than $3$, violating the condition."},"Order":1},{"ErrorType":"misconception","Reason":{"Ar":"بعد تحديد الجزء المتغير $6$، فإن اختيار $12$ يستلزم قيمة ابتدائية $6$ بدلاً من $3$، فلا يحقق الشرط.","En":"With variable part $6$, choice $12$ would require initial value $6$ rather than $3$, violating the condition."},"Order":2},{"ErrorType":"misconception","Reason":{"Ar":"بعد تحديد الجزء المتغير $6$، فإن اختيار $7$ يستلزم قيمة ابتدائية $1$ بدلاً من $3$، فلا يحقق الشرط.","En":"With variable part $6$, choice $7$ would require initial value $1$ rather than $3$, violating the condition."},"Order":3},{"ErrorType":"","Reason":null,"Order":4}]}$mw$,$mw$تكامل المشتقة الثانية الصفرية مرتين يعطي دالة خطية بثابتين.

$y''=0\Rightarrow y'=C_1\Rightarrow y=C_1x+C_2$

1. بتكامل $y''=0$ نجد أن $y'$ ثابت، ومن الشرط الابتدائي $y'(0)=2$ يكون $y'=2$.

2. نكامل مرة ثانية: $y=2x+C_2$، ثم نطبق $y(0)=3$ لتحديد الثابت.

$y(3)=2(3)+3=6+3=9$

$9$ بلا وحدة قياس

$(2x+3)''=0,\quad y'(0)=2,\quad y(0)=3$

لا تخلط شرط المشتقة بشرط الدالة.$mw$,$mw$Integrating a zero second derivative twice gives a linear function with two constants.

$y''=0\Rightarrow y'=C_1\Rightarrow y=C_1x+C_2$

1. Integrate $y''=0$ to obtain constant $y'$; the condition $y'(0)=2$ gives $y'=2$.

2. Integrate again: $y=2x+C_2$, then use $y(0)=3$ to fix the constant.

$y(3)=2(3)+3=6+3=9$

$9$ Dimensionless

$(2x+3)''=0,\quad y'(0)=2,\quad y(0)=3$

Do not confuse the derivative condition with the function condition.$mw$),
(543,337,$mw$9EEB264C8E3B8274F6D4C7FAC54D37970D9BCB21CB0FD8A838C5CA5EB6413E17$mw$,$mw$696947ed3ebb342d3608de33468e7c1f$mw$,$mw$$mw$,$mw${"Id":337,"StageId":4,"CategoryId":15,"Points":15,"TitleAr":"إذا \\(y'=4x\\) و\\(y(0)=3\\)، أوجد \\(y(2)\\).","TitleEn":"Given \\(y'=4x\\), \\(y(0)=3\\), find \\(y(2)\\).","QuestionTextAr":"إذا \\(y'=4x\\) و\\(y(0)=3\\)، أوجد \\(y(2)\\).","QuestionTextEn":"Given \\(y'=4x\\), \\(y(0)=3\\), find \\(y(2)\\).","DetailedSolutionAr":"قاعدة تكامل القوى: ∫x dx = x²/2. إذا كانت y′ = 4x، فإن y = (4/2)x² + C = 2x² + C. من y(0) = 3 نحصل على C = 3. بالتعويض x = 2: ‏y(2) = 2 × 2² + 3 = 11. التحقق: المشتقة y′ = 4x.","DetailedSolutionEn":"Power integration rule: ∫x dx = x²/2. Given y′ = 4x, integrate to y = (4/2)x² + C = 2x² + C. Use y(0) = 3 to find C = 3. Then y(2) = 2 × 2² + 3 = 11. Differentiating yields y′ = 4x.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":1337,"Order":1,"LatexCode":"14","IsCorrect":false},{"Id":1338,"Order":2,"LatexCode":"9","IsCorrect":false},{"Id":1339,"Order":3,"LatexCode":"11","IsCorrect":true},{"Id":1340,"Order":4,"LatexCode":"12","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"ابدأ بتكامل الطرف الأيمن.","En":"Start by integrating the right-hand side."},{"Ar":"استعمل قيمة y عند الصفر لتحديد الثابت ثم عوض المدخل المطلوب.","En":"Use the value at zero to determine the constant and evaluate the requested input."}],"Title":{"Ar":"إذا \\(y'=4x\\) و\\(y(0)=3\\)، أوجد \\(y(2)\\).","En":"Given \\(y'=4x\\), \\(y(0)=3\\), find \\(y(2)\\)."},"Points":15,"Options":[{"Reason":{"Ar":"بعد تحديد الجزء المتغير $8$، فإن اختيار $14$ يستلزم قيمة ابتدائية $6$ بدلاً من $3$، فلا يحقق الشرط.","En":"With variable part $8$, choice $14$ would require initial value $6$ rather than $3$, violating the condition."},"ErrorType":"misconception","IsCorrect":false,"LatexCode":"14"},{"Reason":{"Ar":"بعد تحديد الجزء المتغير $8$، فإن اختيار $9$ يستلزم قيمة ابتدائية $1$ بدلاً من $3$، فلا يحقق الشرط.","En":"With variable part $8$, choice $9$ would require initial value $1$ rather than $3$, violating the condition."},"ErrorType":"misconception","IsCorrect":false,"LatexCode":"9"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"11"},{"Reason":{"Ar":"بعد تحديد الجزء المتغير $8$، فإن اختيار $12$ يستلزم قيمة ابتدائية $4$ بدلاً من $3$، فلا يحقق الشرط.","En":"With variable part $8$, choice $12$ would require initial value $4$ rather than $3$, violating the condition."},"ErrorType":"misconception","IsCorrect":false,"LatexCode":"12"}],"StageId":4,"Question":{"Ar":"إذا \\(y'=4x\\) و\\(y(0)=3\\)، أوجد \\(y(2)\\).","En":"Given \\(y'=4x\\), \\(y(0)=3\\), find \\(y(2)\\)."},"Solution":{"Idea":{"Ar":"نستخدم التكامل لاستعادة الدالة من مشتقتها، والشرط الابتدائي يحدد الثابت.","En":"Integrate to recover the function; the initial condition determines the constant."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"نكامل الطرف الأيمن فنحصل على $y=2x^2+C$.","En":"Integrate the right-hand side to obtain $y=2x^2+C$."},{"Ar":"من $y(0)=3$ نجد $C=3$، فنعوض $x=2$ في الحل.","En":"From $y(0)=3$ we get $C=3$, then substitute $x=2$."}],"Result":{"Ar":"$11$","En":"$11$"},"CommonError":{"Ar":"لا تنس ثابت التكامل أو التعويض بالشرط الابتدائي.","En":"Do not omit the integration constant or initial condition."},"FormulaLatex":"y(x)=y(0)+\\int_0^x g(t)\\,dt","Substitution":{"Ar":"$y(2)=2(2)^2+3=8+3=11$","En":"$y(2)=2(2)^2+3=8+3=11$"},"Verification":{"Ar":"$(2x^2+3)'=4x,\\quad y(0)=3$","En":"$(2x^2+3)'=4x,\\quad y(0)=3$"}},"TrackIds":[15,21],"CategoryId":15,"PrimarySkillId":68,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"ابدأ بتكامل الطرف الأيمن.","En":"Start by integrating the right-hand side."},{"Ar":"استعمل قيمة y عند الصفر لتحديد الثابت ثم عوض المدخل المطلوب.","En":"Use the value at zero to determine the constant and evaluate the requested input."}],"Solution":{"Idea":{"Ar":"نستخدم التكامل لاستعادة الدالة من مشتقتها، والشرط الابتدائي يحدد الثابت.","En":"Integrate to recover the function; the initial condition determines the constant."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"نكامل الطرف الأيمن فنحصل على $y=2x^2+C$.","En":"Integrate the right-hand side to obtain $y=2x^2+C$."},{"Ar":"من $y(0)=3$ نجد $C=3$، فنعوض $x=2$ في الحل.","En":"From $y(0)=3$ we get $C=3$, then substitute $x=2$."}],"Result":{"Ar":"$11$","En":"$11$"},"CommonError":{"Ar":"لا تنس ثابت التكامل أو التعويض بالشرط الابتدائي.","En":"Do not omit the integration constant or initial condition."},"FormulaLatex":"y(x)=y(0)+\\int_0^x g(t)\\,dt","Substitution":{"Ar":"$y(2)=2(2)^2+3=8+3=11$","En":"$y(2)=2(2)^2+3=8+3=11$"},"Verification":{"Ar":"$(2x^2+3)'=4x,\\quad y(0)=3$","En":"$(2x^2+3)'=4x,\\quad y(0)=3$"}},"Distractors":[{"ErrorType":"misconception","Reason":{"Ar":"بعد تحديد الجزء المتغير $8$، فإن اختيار $14$ يستلزم قيمة ابتدائية $6$ بدلاً من $3$، فلا يحقق الشرط.","En":"With variable part $8$, choice $14$ would require initial value $6$ rather than $3$, violating the condition."},"Order":1},{"ErrorType":"misconception","Reason":{"Ar":"بعد تحديد الجزء المتغير $8$، فإن اختيار $9$ يستلزم قيمة ابتدائية $1$ بدلاً من $3$، فلا يحقق الشرط.","En":"With variable part $8$, choice $9$ would require initial value $1$ rather than $3$, violating the condition."},"Order":2},{"ErrorType":"","Reason":null,"Order":3},{"ErrorType":"misconception","Reason":{"Ar":"بعد تحديد الجزء المتغير $8$، فإن اختيار $12$ يستلزم قيمة ابتدائية $4$ بدلاً من $3$، فلا يحقق الشرط.","En":"With variable part $8$, choice $12$ would require initial value $4$ rather than $3$, violating the condition."},"Order":4}]}$mw$,$mw$نستخدم التكامل لاستعادة الدالة من مشتقتها، والشرط الابتدائي يحدد الثابت.

$y(x)=y(0)+\int_0^x g(t)\,dt$

1. نكامل الطرف الأيمن فنحصل على $y=2x^2+C$.

2. من $y(0)=3$ نجد $C=3$، فنعوض $x=2$ في الحل.

$y(2)=2(2)^2+3=8+3=11$

$11$ بلا وحدة قياس

$(2x^2+3)'=4x,\quad y(0)=3$

لا تنس ثابت التكامل أو التعويض بالشرط الابتدائي.$mw$,$mw$Integrate to recover the function; the initial condition determines the constant.

$y(x)=y(0)+\int_0^x g(t)\,dt$

1. Integrate the right-hand side to obtain $y=2x^2+C$.

2. From $y(0)=3$ we get $C=3$, then substitute $x=2$.

$y(2)=2(2)^2+3=8+3=11$

$11$ Dimensionless

$(2x^2+3)'=4x,\quad y(0)=3$

Do not omit the integration constant or initial condition.$mw$),
(544,338,$mw$AAD917A91666A2B2BE2FBD7BACE1207F7E510D7A04F5B721A051312C42124E35$mw$,$mw$2bf1cd75cce9c5144576f34ba332140b$mw$,$mw$$mw$,$mw${"Id":338,"StageId":4,"CategoryId":36,"Points":15,"TitleAr":"أوجد نهاية \\(a_n=\\frac{2}{n+1}\\) عندما \\(n\\to\\infty\\).","TitleEn":"Find limit of \\(a_n=\\frac{2}{n+1}\\) as n tends to infinity.","QuestionTextAr":"أوجد نهاية \\(a_n=\\frac{2}{n+1}\\) عندما \\(n\\to\\infty\\).","QuestionTextEn":"Find limit of \\(a_n=\\frac{2}{n+1}\\) as n tends to infinity.","DetailedSolutionAr":"القانون المستخدم: الكسر ذو البسط الثابت والمقام الذي يزداد إلى ما لا نهاية يتقارب إلى الصفر. للمتتالية aₙ = 2/(n+1)، لأي ε > 0 نختار n أكبر من 2/ε، عندها 0 < 2/(n+1) < ε. إذن lim(aₙ) عندما n → ∞ يساوي 0.","DetailedSolutionEn":"Rule used: A constant divided by a denominator increasing without bound has limit zero. For aₙ = 2/(n+1), given any ε > 0 choose n > 2/ε. Then 0 < 2/(n+1) < ε, proving lim(n→∞) aₙ = 0.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":1341,"Order":1,"LatexCode":"1","IsCorrect":false},{"Id":1342,"Order":2,"LatexCode":"2","IsCorrect":false},{"Id":1343,"Order":3,"LatexCode":"+\\infty","IsCorrect":false},{"Id":1344,"Order":4,"LatexCode":"0","IsCorrect":true}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"راقب سلوك الحد عندما تكبر رتبة المتتالية.","En":"Examine how the term behaves as its index increases."},{"Ar":"قارن الكسر بكمية تتناقص إلى الصفر عندما يكبر المقام.","En":"Compare the fraction with a quantity tending to zero as its denominator grows."}],"Title":{"Ar":"أوجد نهاية \\(a_n=\\frac{2}{n+1}\\) عندما \\(n\\to\\infty\\).","En":"Find limit of \\(a_n=\\frac{2}{n+1}\\) as n tends to infinity."},"Points":15,"Options":[{"Reason":{"Ar":"القيمة $1$ حد موجب ثابت، بينما يمكن جعل الكسر أصغر من أي عدد موجب بتكبير المقام.","En":"Choice $1$ is a fixed positive value, but the fraction can be made smaller than any positive number by increasing the denominator."},"ErrorType":"misconception","IsCorrect":false,"LatexCode":"1"},{"Reason":{"Ar":"القيمة $2$ حد موجب ثابت، بينما يمكن جعل الكسر أصغر من أي عدد موجب بتكبير المقام.","En":"Choice $2$ is a fixed positive value, but the fraction can be made smaller than any positive number by increasing the denominator."},"ErrorType":"misconception","IsCorrect":false,"LatexCode":"2"},{"Reason":{"Ar":"خلط ازدياد المقام مع ازدياد الكسر؛ زيادة المقام تخفض كسر البسط الثابت.","En":"Confuses growth of the denominator with growth of the fraction; a fixed numerator gives a decreasing fraction."},"ErrorType":"misconception","IsCorrect":false,"LatexCode":"+\\infty"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"0"}],"StageId":4,"Question":{"Ar":"أوجد نهاية \\(a_n=\\frac{2}{n+1}\\) عندما \\(n\\to\\infty\\).","En":"Find limit of \\(a_n=\\frac{2}{n+1}\\) as n tends to infinity."},"Solution":{"Idea":{"Ar":"البسط ثابت والمقام يزداد بلا حد.","En":"The numerator stays fixed as the denominator grows without bound."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"البسط $2$ ثابت موجب والمقام $n+1$ يزداد بلا حد.","En":"The numerator $2$ is positive and fixed while $n+1$ grows without bound."},{"Ar":"لـ $n\\ge1$ لدينا $0<\\frac{2}{n+1}\\le\\frac{2}n$؛ الطرف الأعلى يقترب من الصفر.","En":"For $n\\ge1$, $0<\\frac{2}{n+1}\\le\\frac{2}n$; the upper bound tends to zero."}],"Result":{"Ar":"$0$","En":"$0$"},"CommonError":{"Ar":"لا تخلط الحد الأول بنهاية المتتالية.","En":"Do not confuse the first term with the sequence limit."},"FormulaLatex":"\\lim_{n\\to\\infty}\\frac{c}{n+1}=0\\quad(c>0)","Substitution":{"Ar":"$\\lim_{n\\to\\infty}\\frac{2}{n+1}=0$","En":"$\\lim_{n\\to\\infty}\\frac{2}{n+1}=0$"},"Verification":{"Ar":"لكل $\\varepsilon>0$ يكفي اختيار $n>2/\\varepsilon$ كي يكون الحد أصغر من $\\varepsilon$.","En":"For each $\\varepsilon>0$, choosing $n>2/\\varepsilon$ makes the term less than $\\varepsilon$."}},"TrackIds":[13,20],"CategoryId":36,"PrimarySkillId":72,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"راقب سلوك الحد عندما تكبر رتبة المتتالية.","En":"Examine how the term behaves as its index increases."},{"Ar":"قارن الكسر بكمية تتناقص إلى الصفر عندما يكبر المقام.","En":"Compare the fraction with a quantity tending to zero as its denominator grows."}],"Solution":{"Idea":{"Ar":"البسط ثابت والمقام يزداد بلا حد.","En":"The numerator stays fixed as the denominator grows without bound."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"البسط $2$ ثابت موجب والمقام $n+1$ يزداد بلا حد.","En":"The numerator $2$ is positive and fixed while $n+1$ grows without bound."},{"Ar":"لـ $n\\ge1$ لدينا $0<\\frac{2}{n+1}\\le\\frac{2}n$؛ الطرف الأعلى يقترب من الصفر.","En":"For $n\\ge1$, $0<\\frac{2}{n+1}\\le\\frac{2}n$; the upper bound tends to zero."}],"Result":{"Ar":"$0$","En":"$0$"},"CommonError":{"Ar":"لا تخلط الحد الأول بنهاية المتتالية.","En":"Do not confuse the first term with the sequence limit."},"FormulaLatex":"\\lim_{n\\to\\infty}\\frac{c}{n+1}=0\\quad(c>0)","Substitution":{"Ar":"$\\lim_{n\\to\\infty}\\frac{2}{n+1}=0$","En":"$\\lim_{n\\to\\infty}\\frac{2}{n+1}=0$"},"Verification":{"Ar":"لكل $\\varepsilon>0$ يكفي اختيار $n>2/\\varepsilon$ كي يكون الحد أصغر من $\\varepsilon$.","En":"For each $\\varepsilon>0$, choosing $n>2/\\varepsilon$ makes the term less than $\\varepsilon$."}},"Distractors":[{"ErrorType":"misconception","Reason":{"Ar":"القيمة $1$ حد موجب ثابت، بينما يمكن جعل الكسر أصغر من أي عدد موجب بتكبير المقام.","En":"Choice $1$ is a fixed positive value, but the fraction can be made smaller than any positive number by increasing the denominator."},"Order":1},{"ErrorType":"misconception","Reason":{"Ar":"القيمة $2$ حد موجب ثابت، بينما يمكن جعل الكسر أصغر من أي عدد موجب بتكبير المقام.","En":"Choice $2$ is a fixed positive value, but the fraction can be made smaller than any positive number by increasing the denominator."},"Order":2},{"ErrorType":"misconception","Reason":{"Ar":"خلط ازدياد المقام مع ازدياد الكسر؛ زيادة المقام تخفض كسر البسط الثابت.","En":"Confuses growth of the denominator with growth of the fraction; a fixed numerator gives a decreasing fraction."},"Order":3},{"ErrorType":"","Reason":null,"Order":4}]}$mw$,$mw$البسط ثابت والمقام يزداد بلا حد.

$\lim_{n\to\infty}\frac{c}{n+1}=0\quad(c>0)$

1. البسط $2$ ثابت موجب والمقام $n+1$ يزداد بلا حد.

2. لـ $n\ge1$ لدينا $0<\frac{2}{n+1}\le\frac{2}n$؛ الطرف الأعلى يقترب من الصفر.

$\lim_{n\to\infty}\frac{2}{n+1}=0$

$0$ بلا وحدة قياس

لكل $\varepsilon>0$ يكفي اختيار $n>2/\varepsilon$ كي يكون الحد أصغر من $\varepsilon$.

لا تخلط الحد الأول بنهاية المتتالية.$mw$,$mw$The numerator stays fixed as the denominator grows without bound.

$\lim_{n\to\infty}\frac{c}{n+1}=0\quad(c>0)$

1. The numerator $2$ is positive and fixed while $n+1$ grows without bound.

2. For $n\ge1$, $0<\frac{2}{n+1}\le\frac{2}n$; the upper bound tends to zero.

$\lim_{n\to\infty}\frac{2}{n+1}=0$

$0$ Dimensionless

For each $\varepsilon>0$, choosing $n>2/\varepsilon$ makes the term less than $\varepsilon$.

Do not confuse the first term with the sequence limit.$mw$);
DO $audit$
DECLARE b record; d "CurriculumDraftItems"%ROWTYPE; p "Problems"%ROWTYPE; tr int; sk int; n int; actor int;
BEGIN
 FOR b IN SELECT * FROM reviewed_batch ORDER BY source LOOP
  PERFORM pg_advisory_xact_lock(-b.source::bigint);
  SELECT * INTO STRICT d FROM "CurriculumDraftItems" WHERE "Id"=b.draft FOR UPDATE;
  SELECT * INTO STRICT p FROM "Problems" WHERE "Id"=b.source FOR UPDATE;
  PERFORM 1 FROM "QuestionOptions" WHERE "ProblemId"=b.source FOR UPDATE;
  actor:=d."OwnerUserId"; tr:=(b.wizard->'TrackIds'->>0)::int; sk:=(b.wizard->>'PrimarySkillId')::int;
  IF d."SourceProblemId" IS DISTINCT FROM b.source OR d."Revision"<>0 OR d."EditorialStatus"<>'Draft' OR d."PublishedProblemId" IS NOT NULL OR d."SourceFingerprint" IS DISTINCT FROM b.fp OR md5(d."WizardJson") IS DISTINCT FROM b.draft_hash OR upper(encode(sha256(decode(b.source_hex,'hex')),'hex'))<>b.fp OR (SELECT json_build_object('Id',pp."Id",'StageId',pp."StageId",'CategoryId',pp."CategoryId",'Points',pp."Points",'TitleAr',pp."TitleAr",'TitleEn',pp."TitleEn",'QuestionTextAr',pp."QuestionTextAr",'QuestionTextEn',pp."QuestionTextEn",'DetailedSolutionAr',pp."DetailedSolutionAr",'DetailedSolutionEn',pp."DetailedSolutionEn",'YoutubeSolutionUrl',pp."YoutubeSolutionUrl",'EditorialDetailsJson',pp."EditorialDetailsJson",'Options',(select json_agg(json_build_object('Id',o."Id",'Order',o."Order",'LatexCode',o."LatexCode",'IsCorrect',o."IsCorrect") order by o."Order",o."Id") from "QuestionOptions" o where o."ProblemId"=pp."Id"))::jsonb FROM "Problems" pp WHERE pp."Id"=b.source) IS DISTINCT FROM b.snapshot THEN RAISE EXCEPTION 'Source/draft conflict: %',b.draft; END IF;
  IF NOT EXISTS(SELECT 1 FROM "Users" WHERE "Id"=actor AND "Role"='Admin' AND "IsActive" AND NOT "StaffSetupPending") OR (SELECT count(*) FROM "CurriculumDraftItems" WHERE "SourceProblemId"=b.source AND "EditorialStatus" NOT IN ('Published','Withdrawn'))<>1 THEN RAISE EXCEPTION 'Owner/open-draft conflict: %',b.draft; END IF;
  PERFORM 1 FROM "LearningTracks" WHERE "Id" IN (SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int) ORDER BY "Id" FOR UPDATE;
  IF NOT EXISTS(SELECT 1 FROM "LearningTracks" WHERE "Id"=tr AND "StageId"=p."StageId" AND "IsPublished" AND "Revision"<2147483647) OR NOT EXISTS(SELECT 1 FROM "Categories" WHERE "Id"=p."CategoryId" AND "StageId"=p."StageId") OR NOT EXISTS(SELECT 1 FROM "CurriculumSkills" s JOIN "CurriculumDomains" dm ON dm."Id"=s."DomainId" WHERE s."Id"=sk AND s."StageId"=p."StageId" AND s."CategoryId"=p."CategoryId" AND s."IsPublished" AND dm."IsPublished") OR NOT EXISTS(SELECT 1 FROM "LearningTrackCategories" WHERE "TrackId"=tr AND "CategoryId"=p."CategoryId") OR NOT EXISTS(SELECT 1 FROM "LearningTrackSkills" WHERE "TrackId"=tr AND "SkillId"=sk) OR (SELECT array_agg("TrackId" ORDER BY "TrackId") FROM "LearningTrackProblems" WHERE "ProblemId"=b.source) IS DISTINCT FROM ARRAY(SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int ORDER BY 1) OR (SELECT array_agg("SkillId" ORDER BY "SkillId") FROM "CurriculumProblemSkills" WHERE "ProblemId"=b.source) IS DISTINCT FROM ARRAY[sk] OR NOT EXISTS(SELECT 1 FROM "CurriculumProblemSkills" WHERE "ProblemId"=b.source AND "SkillId"=sk AND "IsPrimary") OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(b.wizard->'TrackIds') j(id) LEFT JOIN "LearningTracks" lt ON lt."Id"=j.id::int WHERE lt."Id" IS NULL OR lt."StageId"<>p."StageId" OR lt."Revision">=2147483647 OR NOT EXISTS(SELECT 1 FROM "LearningTrackCategories" WHERE "TrackId"=lt."Id" AND "CategoryId"=p."CategoryId") OR NOT EXISTS(SELECT 1 FROM "LearningTrackSkills" WHERE "TrackId"=lt."Id" AND "SkillId"=sk)) THEN RAISE EXCEPTION 'Scope conflict: %',b.draft; END IF;
  IF EXISTS(SELECT 1 FROM "Problems" q WHERE q."Id"<>b.source AND q."StageId"=p."StageId" AND (upper(regexp_replace(btrim(q."QuestionTextAr"),'[[:space:]]+',' ','g'))=upper(regexp_replace(btrim(p."QuestionTextAr"),'[[:space:]]+',' ','g')) OR upper(regexp_replace(btrim(q."QuestionTextEn"),'[[:space:]]+',' ','g'))=upper(regexp_replace(btrim(p."QuestionTextEn"),'[[:space:]]+',' ','g')))) THEN RAISE EXCEPTION 'Duplicate: %',b.draft; END IF;
  IF b.wizard#>>'{Question,Ar}' IS DISTINCT FROM p."QuestionTextAr" OR b.wizard#>>'{Question,En}' IS DISTINCT FROM p."QuestionTextEn" OR length(b.flat_ar)>12000 OR length(b.flat_en)>12000 THEN RAISE EXCEPTION 'Question/length conflict: %',b.draft; END IF;
  UPDATE "Problems" SET "TitleAr"=b.wizard#>>'{Title,Ar}',"TitleEn"=b.wizard#>>'{Title,En}',"DetailedSolutionAr"=b.flat_ar,"DetailedSolutionEn"=b.flat_en,"EditorialDetailsJson"=b.metadata WHERE "Id"=b.source;
  UPDATE "CurriculumDraftItems" SET "WizardJson"=b.wizard::text,"EditorialStatus"='Published',"Revision"=4,"SubmittedAtUtc"=now(),"ReviewedAtUtc"=now(),"ReviewedByUserId"=actor,"ReviewNote"='Owner-authorized SQL maintenance; AI educational review and source-locked verification. Existing draft owner recorded for attribution; no API login.',"PublishedAtUtc"=now(),"PublishedProblemId"=b.source WHERE "Id"=b.draft;
  UPDATE "LearningTracks" SET "Revision"="Revision"+1 WHERE "Id" IN (SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int);
  INSERT INTO "PlatformActivityEvents"("ActorUserId","ActorRole","Action","Resource","ResourceId","Origin","CreatedAtUtc") SELECT actor,'Admin',action,'EditorialProblem',b.draft::text,'owner_sql',now() FROM unnest(ARRAY['EditorialDraftEdited','EditorialDraftSubmitted','EditorialDraftApproved','EditorialAmendmentPublished']) action;
 END LOOP;
END $audit$;
COMMIT;
